window.RiskManagement=(()=>{
 const levels=['High','Medium','Low'],colors={High:'#f15b6c',Medium:'#f2ad25',Low:'#1fb78d'};
 const level=r=>{const scores={Low:1,Medium:2,High:3},score=(scores[r.likelihood]||1)*(scores[r.impact]||1);return score>=6?'High':score>=3?'Medium':'Low'};
 async function mount(container,context){let records={},errors=[],filters={project:'all',status:'all',level:'all',owner:'all',query:''},page=1,loading=false;const pageSize=Number(window.WorkspaceSettings?.read().pageSize)||10;const {projects,members,avatar}=context;
 const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
 async function load(){loading=true;container.innerHTML='<p role="status">Loading risk registers…</p>';const results=await Promise.allSettled(projects.map(async p=>[p.id,(await ProjectAPI.request('/api/projects/'+encodeURIComponent(p.id)+'/tools')).data.risks]));records={};errors=[];results.forEach((r,i)=>r.status==='fulfilled'?records[r.value[0]]=r.value[1]:errors.push(projects[i].name));loading=false;if(container.isConnected)draw()}
 function draw(){const all=projects.flatMap(p=>(records[p.id]?.entries||[]).map(r=>({...r,project:p,level:level(r)}))),rows=all.filter(r=>(filters.project==='all'||r.project.id===filters.project)&&(filters.status==='all'||r.status===filters.status)&&(filters.level==='all'||r.level===filters.level)&&(filters.owner==='all'||(r.owner||'unassigned')===filters.owner)&&[r.name,r.mitigation,r.contingency,r.project.name,members.find(m=>m.id===r.owner)?.name].join(' ').toLowerCase().includes(filters.query.toLowerCase()));
 const counts=levels.map(status=>({status,count:rows.filter(r=>r.level===status).length}));let angle=0;const stops=counts.filter(x=>x.count).map(x=>{const from=angle;angle+=x.count/rows.length*100;return `${colors[x.status]} ${from}% ${angle}%`}).join(',')||'#e6eef8 0% 100%';page=Math.min(page,Math.max(1,Math.ceil(rows.length/pageSize)));
 const select=(key,label,values)=>`<label>${label}<select data-rm-filter="${key}">${options(values,filters[key])}</select></label>`;
 container.innerHTML=`<div class="pf-heading"><div><h1><span class="fa-solid fa-shield-halved" aria-hidden="true"></span> Risk Management</h1><p>Identify, assess, and manage risks across your projects.</p></div><div class="work-actions"><button class="secondary" data-rm-refresh>Refresh</button><button class="primary" data-rm-add>+ Add Risk</button></div></div>${errors.length?`<p role="alert" class="wr-warning">Some registers could not load: ${errors.map(esc).join(', ')}. Refresh to retry; summaries are partial.</p>`:''}<div class="pf-layout"><div class="pf-main"><div class="pf-kpis rm-kpis">${[['Total Risks',rows.length,'circle-exclamation','blue'],...counts.map(x=>[x.status+' Risk',x.count,x.status==='Low'?'shield-halved':'triangle-exclamation',x.status==='High'?'red':x.status==='Medium'?'orange':'green'])].map(([label,value,icon,color])=>`<article class="panel pf-kpi ${color}"><i><span class="fa-solid fa-${icon}" aria-hidden="true"></span></i><div><span>${label}</span><strong>${value}</strong><small>Matching current filters</small></div></article>`).join('')}</div><div class="pf-charts"><section class="panel"><h2>Risk Distribution</h2><div class="pf-donut-layout"><div class="pf-donut" style="background:conic-gradient(${stops})"><span><b>${rows.length}</b>Total Risks</span></div><div class="pf-chart-legend">${counts.map(x=>`<div><i style="background:${colors[x.status]}"></i>${x.status}<b>${x.count}</b></div>`).join('')}</div></div></section><section class="panel"><h2>Risks by Project</h2><div class="pf-phases">${projects.filter(p=>rows.some(r=>r.project.id===p.id)).map(p=>{const n=rows.filter(r=>r.project.id===p.id).length;return `<div><span>${esc(p.name)}</span><div class="pf-phase-track"><i style="width:${n/Math.max(1,rows.length)*100}%"></i></div><small>${n}</small></div>`}).join('')||'<p class="pf-empty">No matching risks.</p>'}</div></section><section class="panel"><h2>Risk Assessment Matrix</h2><p class="pf-caption">Likelihood × impact · current risks</p><table class="rm-matrix"><thead><tr><th>Likelihood</th>${['Low','Medium','High'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${['High','Medium','Low'].map(l=>`<tr><th>${l}</th>${['Low','Medium','High'].map(i=>`<td style="background:${colors[level({likelihood:l,impact:i})]}25">${rows.filter(r=>r.likelihood===l&&r.impact===i).length}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="pf-caption">Columns: impact. No historical trend is available.</p></section></div><section class="panel pf-projects"><h2>Risk List</h2><input class="rm-search" aria-label="Search risks" data-rm-search placeholder="Search risks, mitigations, projects or owners…" value="${esc(filters.query)}"><div class="bug-table-wrap"><table class="pf-table"><thead><tr><th>Risk</th><th>Project</th><th>Level</th><th>Likelihood</th><th>Impact</th><th>Status</th><th>Owner</th><th>Review Date</th><th>Mitigation</th><th>Actions</th></tr></thead><tbody>${rows.slice((page-1)*pageSize,page*pageSize).map(r=>`<tr><td>${esc(r.name)}</td><td><button class="text-btn" data-project-dashboard="${esc(r.project.id)}">${esc(r.project.name)}</button></td><td><span class="pf-status-pill" style="--status:${colors[r.level]}">${r.level}</span></td><td>${esc(r.likelihood)}</td><td>${esc(r.impact)}</td><td>${esc(r.status)}</td><td><div class="pf-owner">${avatar(members.find(m=>m.id===r.owner))}${esc(members.find(m=>m.id===r.owner)?.name||'Unassigned')}</div></td><td>${esc(r.date||'—')}</td><td class="rm-mitigation">${esc(r.mitigation)}</td><td><button class="text-btn" data-rm-edit="${esc(r.id)}" data-rm-project="${esc(r.project.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="10">No risks match. Add a risk to start tracking.</td></tr>'}</tbody></table></div><div class="rm-pagination"><span>${rows.length?((page-1)*pageSize+1):0}–${Math.min(page*pageSize,rows.length)} of ${rows.length} risks</span><button class="secondary" data-rm-page="-1" ${page===1?'disabled':''}>Previous</button><button class="secondary" data-rm-page="1" ${page*pageSize>=rows.length?'disabled':''}>Next</button></div><p class="pf-caption">Risk score: Low=1, Medium=2, High=3. Likelihood × impact: 1–2 Low, 3–4 Medium, 6–9 High. Counts include closed risks unless filtered.</p></section></div><div class="pf-right"><section class="panel rm-filters"><h2>Filters</h2>${select('project','Project',[['all','All Projects'],...projects.map(p=>[p.id,p.name])])}${select('status','Status',[['all','All Statuses'],...['Open','Mitigating','Closed'].map(x=>[x,x])])}${select('level','Risk Level',[['all','All Levels'],...levels.map(x=>[x,x])])}${select('owner','Owner',[['all','All Owners'],['unassigned','Unassigned'],...members.map(m=>[m.id,m.name])])}<button class="text-btn" data-rm-clear>Clear Filters</button></section><section class="panel"><h2>Risk Summary</h2>${['Open','Mitigating','Closed'].map(s=>`<div class="rm-summary"><span>${s}</span><b>${rows.filter(r=>r.status===s).length}</b></div>`).join('')}</section><section class="panel"><h2>Upcoming Reviews</h2>${rows.filter(r=>r.date&&r.status!=='Closed').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5).map(r=>`<div class="wr-highlight"><button class="text-btn" data-rm-edit="${esc(r.id)}" data-rm-project="${esc(r.project.id)}">${esc(r.name)}</button><p>${esc(r.date)} · ${esc(r.project.name)}</p></div>`).join('')||'<p class="pf-empty">No scheduled reviews.</p>'}</section></div></div>`;
 }
 async function editor(projectId,id){const project=projects.find(p=>p.id===projectId);if(!project)return;const dialog=document.createElement('dialog');dialog.className='rm-editor';dialog.innerHTML='<button class="secondary" data-rm-close>Back to Risk Management</button><div class="rm-editor-content"></div>';document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-rm-close]').onclick=()=>dialog.close();dialog.onclose=()=>{dialog.remove();if(container.isConnected){history.replaceState(null,'','#risks');load()}};await ProjectTools.mount(dialog.querySelector('.rm-editor-content'),{project,members,tasks:context.issues.filter(t=>t.projectId===project.id),avatar,initialEdit:id||'new',preserveHash:true},'risks')}
 container.onclick=e=>{const b=e.target.closest('button');if(!b||loading)return;if(b.hasAttribute('data-rm-refresh'))load();if(b.dataset.rmPage){page+=Number(b.dataset.rmPage);draw()}if(b.hasAttribute('data-rm-clear')){filters={project:'all',status:'all',level:'all',owner:'all',query:''};page=1;draw()}if(b.dataset.rmEdit)editor(b.dataset.rmProject,b.dataset.rmEdit);if(b.hasAttribute('data-rm-add')){if(!projects.length){alert('Create a project before adding risks.');return}const d=document.createElement('dialog');d.className='pt-editor';d.innerHTML=`<form><h2>Add Risk</h2><label>Project<select name="project">${options(projects.map(p=>[p.id,p.name]),filters.project)}</select></label><div class="work-actions"><button type="button" class="secondary">Cancel</button><button class="primary">Continue</button></div></form>`;document.body.append(d);d.showModal();d.querySelector('button[type=button]').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('form').onsubmit=e=>{e.preventDefault();const id=new FormData(e.target).get('project');d.close();editor(id)}}};
 container.onchange=e=>{if(e.target.dataset.rmFilter){filters[e.target.dataset.rmFilter]=e.target.value;page=1;draw()}};
 container.oninput=e=>{if(e.target.hasAttribute('data-rm-search')){filters.query=e.target.value;const pos=e.target.selectionStart;page=1;draw();const input=container.querySelector('[data-rm-search]');input.focus();input.setSelectionRange(pos,pos)}};
 await load();
 }
 return {mount,level};
})();
